import { retrySchedule } from './src/retry-schedule.js';
const t = (fn) => { try { fn(); return 'no-throw'; } catch (e) { return e.constructor.name; } };

// R2: retries 0
console.log(JSON.stringify(retrySchedule({retries:0,baseMs:10,factor:1,maxMs:10,jitter:'none'})));
// R1/R6: TypeError vs RangeError priority
console.log(t(()=>retrySchedule({retries:2.5,baseMs:10,factor:1,maxMs:5,jitter:'none'}))); // TypeError (retries invalid beats baseMs>maxMs)
console.log(t(()=>retrySchedule({retries:1,baseMs:10,factor:1,maxMs:5,jitter:'none'})));   // RangeError
console.log(t(()=>retrySchedule('x')));                                                     // TypeError
console.log(t(()=>retrySchedule({retries:1,baseMs:1,factor:1,maxMs:10,jitter:'none'})));    // missing rand ok
console.log(t(()=>retrySchedule({retries:1,baseMs:1,factor:1,maxMs:10,jitter:'full'})));    // TypeError: no rand
console.log(t(()=>retrySchedule({retries:101,baseMs:1,factor:1,maxMs:10,jitter:'none'})));  // TypeError
console.log(t(()=>retrySchedule({retries:1,baseMs:1,factor:0.5,maxMs:10,jitter:'none'})));  // TypeError factor<1
console.log(t(()=>retrySchedule({retries:1,baseMs:NaN,factor:1,maxMs:10,jitter:'none'})));  // TypeError
// R6: rand return validation
let i=0;
console.log(t(()=>retrySchedule({retries:2,baseMs:100,factor:2,maxMs:1000,jitter:'full'},()=>{i++; return i===2?1.5:0.5}))); // RangeError
console.log(t(()=>retrySchedule({retries:1,baseMs:100,factor:2,maxMs:1000,jitter:'equal'},()=>NaN))); // RangeError
console.log(t(()=>retrySchedule({retries:1,baseMs:100,factor:2,maxMs:1000,jitter:'full'},()=>-0.1))); // RangeError
// R4: rand called exactly once per entry, in order; none never calls
const calls=[];
let v=[0.5,0.0];
retrySchedule({retries:2,baseMs:100,factor:2,maxMs:1000,jitter:'full'},()=>v.shift());
console.log('full r=0.5,0:', JSON.stringify(retrySchedule({retries:2,baseMs:100,factor:2,maxMs:1000,jitter:'full'},()=>[0.5,0][calls.length++] ))));
console.log('equal r=0:', JSON.stringify(retrySchedule({retries:2,baseMs:100,factor:2,maxMs:1000,jitter:'equal'},()=>0)));
// R5: rounds to 0 -> 1
console.log('tiny full r=0:', JSON.stringify(retrySchedule({retries:1,baseMs:1,factor:1,maxMs:1000,jitter:'full'},()=>0)));
// R4: equal formula check r=0.5 -> cap/2+cap/4
console.log('equal r=0.5:', JSON.stringify(retrySchedule({retries:1,baseMs:100,factor:2,maxMs:1000,jitter:'equal'},()=>0.5)));
// immutability
const o={retries:2,baseMs:100,factor:2,maxMs:1000,jitter:'none'};
retrySchedule(o);
console.log('opts unchanged:', JSON.stringify(o));
"

